on conflict (id) do update
  set payload = excluded.payload,
      updated_at = now();

on conflict (page_key, section_key) do update
  set payload = excluded.payload,
      status = 'published',
      sort_order = excluded.sort_order,
      published_at = coalesce(page_sections.published_at, excluded.published_at),
      updated_at = now();
